<?php
use function Fillico\{h,productCard};
$param=static fn($key)=>is_string($_GET[$key]??null)?$_GET[$key]:'';
$category=$param('category');$query=$param('q');$filter=$param('filter');$sort=$param('sort');$inStock=$param('stock')==='1';$maxPrice=ctype_digit($param('max'))?(int)$param('max'):0;
$normalize=static function(string $v):string {
    $v=mb_strtolower($v,'UTF-8');
    $groups=['a'=>'àáạảãâầấậẩẫăằắặẳẵ','e'=>'èéẹẻẽêềếệểễ','i'=>'ìíịỉĩ','o'=>'òóọỏõôồốộổỗơờớợởỡ','u'=>'ùúụủũưừứựửữ','y'=>'ỳýỵỷỹ','d'=>'đ'];
    foreach($groups as $to=>$from)foreach(mb_str_split($from) as $char)$v=str_replace($char,$to,$v);return $v;
};
$results=array_values(array_filter($products,static function($p)use($category,$query,$filter,$inStock,$maxPrice,$normalize){
    return (!$category||$p['category']===$category)&&(!$query||str_contains($normalize($p['name'].' '.$p['category']),$normalize($query)))&&(!$inStock||array_sum(array_column($p['variants'],'stock'))>0)&&(!$maxPrice||min(array_column($p['variants'],'price'))<=$maxPrice)&&($filter!=='new'||($p['badge']??'')==='Mới')&&($filter!=='sale'||count(array_filter($p['variants'],fn($v)=>($v['originalPrice']??0)>$v['price']))>0);
}));
usort($results,static fn($a,$b)=>match($sort){'price-asc'=>min(array_column($a['variants'],'price'))<=>min(array_column($b['variants'],'price')),'price-desc'=>min(array_column($b['variants'],'price'))<=>min(array_column($a['variants'],'price')),'name'=>strcmp($a['name'],$b['name']),default=>$b['featured']<=>$a['featured']});
?>
<nav class="breadcrumb"><a href="/">Trang chủ</a><span>› Sản phẩm</span></nav><div class="catalog-heading"><span class="eyebrow">FILLICO COLLECTION</span><h1><?= h($filter==='favorites'?'Những điều bạn yêu thích.':($category?:'Chọn điều tốt, cho mỗi ngày.')) ?></h1><p>Khám phá những sản phẩm được chọn lựa cho không gian sống và lưu trú.</p></div>
<form class="catalog-layout" action="/san-pham"><aside class="catalog-sidebar"><h3>Bộ lọc sản phẩm</h3><h4>Danh mục</h4><select name="category" aria-label="Danh mục"><option value="">Tất cả sản phẩm</option><?php foreach($categories as $cat): ?><option <?= $cat===$category?'selected':'' ?>><?= h($cat) ?></option><?php endforeach ?></select><h4>Khoảng giá</h4><select name="max" aria-label="Lọc theo giá"><?php foreach([0=>'Tất cả mức giá',100000=>'Đến 100.000₫',200000=>'Đến 200.000₫',300000=>'Đến 300.000₫'] as $value=>$label): ?><option value="<?= $value ?>" <?= $maxPrice===$value?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select><label class="checkbox"><input type="checkbox" name="stock" value="1" <?= $inStock?'checked':'' ?>> Chỉ sản phẩm còn hàng</label><h4>Bộ sưu tập</h4><select name="filter" aria-label="Bộ sưu tập"><?php foreach([''=>'Tất cả','new'=>'Mới','sale'=>'Ưu đãi','favorites'=>'Yêu thích'] as $value=>$label): ?><option value="<?= $value ?>" <?= $filter===$value?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select><button class="btn btn-primary full-width" style="margin-top:20px">Áp dụng bộ lọc</button><a class="text-link" href="/san-pham">Xóa bộ lọc</a></aside><section class="catalog-results"><div class="catalog-toolbar"><div class="catalog-search"><input name="q" value="<?= h($query) ?>" placeholder="Bạn đang tìm sản phẩm gì?" aria-label="Tìm trong danh sách sản phẩm"></div><select name="sort" aria-label="Sắp xếp sản phẩm"><?php foreach(['featured'=>'Đề xuất cho bạn','price-asc'=>'Giá: thấp đến cao','price-desc'=>'Giá: cao đến thấp','name'=>'Tên: A đến Z'] as $value=>$label): ?><option value="<?= $value ?>" <?= $sort===$value?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select><button class="btn btn-outline">Tìm kiếm</button></div><p class="results-top" data-result-count><?= count($results) ?> sản phẩm</p><div class="product-grid catalog-grid" <?= $filter==='favorites'?'data-favorites-only':'' ?>><?php foreach($results as $p)productCard($p); ?></div><div class="empty-state" data-catalog-empty <?= $results?'hidden':'' ?>><h2>Chưa tìm thấy sản phẩm</h2><p>Thử từ khóa khác hoặc bỏ bớt bộ lọc.</p><a class="btn btn-primary" href="/san-pham">Xem tất cả sản phẩm</a></div></section></form>
